#include <Trade/Trade.mqh>
input double lotSize = 0.1; // Lote padrão

CTrade trade; // Cria um objeto para operações de trading

//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit()
  {
   //---
   return(INIT_SUCCEEDED);
  }
//+------------------------------------------------------------------+
//| Expert deinitialization function                                 |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
  {
   //---
  }

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
  {
   double sma20 = iMA(NULL, 0, 20, 0, MODE_SMA, PRICE_CLOSE);
   double sma200 = iMA(NULL, 0, 200, 0, MODE_SMA, PRICE_CLOSE);
   double closePrice = iClose(NULL, 0, 0);

   bool positionExists = false;
   ENUM_POSITION_TYPE currentPositionType = POSITION_TYPE_BUY;
   ulong positionTicket = 0;

   // Verifica se já existe uma posição aberta
   if (PositionsTotal() > 0)
     {
      positionTicket = PositionGetTicket(0);
      if (PositionSelectByTicket(positionTicket))
        {
         currentPositionType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);
         positionExists = true;
        }
     }

   // Se a tendência é de alta e não há posição de compra aberta
   if (sma200 < closePrice && closePrice > sma20)
     {
      // Se existir uma posição de venda, ela será fechada
      if (positionExists && currentPositionType == POSITION_TYPE_SELL)
        {
         if (trade.PositionClose(positionTicket))
           {
            Print("Vendeu posição fechada com sucesso: ", positionTicket);
            positionExists = false;
           }
         else
           {
            Print("Erro ao fechar posição de venda: ", _LastError);
           }
        }

      // Abre uma posição de compra se não existe uma posição
      if (!positionExists)
        {
         if (trade.Buy(lotSize, NULL, closePrice, 0, 0, "Comprado por cruzar SMA20"))
           {
            Print("Comprado por cruzar SMA20");
           }
         else
           {
            Print("Erro ao abrir posição de compra: ", _LastError);
           }
        }
     }
   // Se a tendência é de baixa e não há posição de venda aberta
   else if (sma200 > closePrice && closePrice < sma20)
     {
      // Se existir uma posição de compra, ela será fechada
      if (positionExists && currentPositionType == POSITION_TYPE_BUY)
        {
         if (trade.PositionClose(positionTicket))
           {
            Print("Compra fechada com sucesso: ", positionTicket);
            positionExists = false;
           }
         else
           {
            Print("Erro ao fechar posição de compra: ", _LastError);
           }
        }

      // Abre uma posição de venda se não existe uma posição
      if (!positionExists)
        {
         if (trade.Sell(lotSize, NULL, closePrice, 0, 0, "Vendido por cruzar SMA20"))
           {
            Print("Vendido por cruzar SMA20");
           }
         else
           {
            Print("Erro ao abrir posição de venda: ", _LastError);
           }
        }
     }
  }
//+------------------------------------------------------------------+

resposta:
Para resolver o problema de o robô **não estar fechando a ordem anterior**, vamos analisar os pontos críticos e apresentar um código mais robusto. Os principais motivos podem ser:

1. **A condição de cruzamento das médias móveis pode não estar sendo detectada em tempo real** (ex.: atraso da indicação ou o preço ainda não ultrapassou o cruzamento no tick atual).
2. **O fechamento da posição existente está falhando silenciosamente** (retorna `false` ou gera erro sem ser registrado corretamente).
3. **A variável `positionExists` não é atualizada após o fechamento**, causando que a próxima verificação não veja a posição como fechada.
4. **Uso incorreto do `PositionGetTicket(0)`** – ele retorna o ticket da primeira posição, mas se houver múltiplas posições isso pode levar a fechar a errada.

### Solução Recomendada

Reescrevemos o `OnTick()` para:

- Calcular diretamente se estamos em tendência de alta ou baixa usando booleanos.
- Fechar qualquer posição oposta antes de abrir nova.
- Registrar o sucesso ou erro de cada operação.
- Usar `PositionsTotal()` para saber quantas posições existem (útil para evitar confusão).

Abaixo está o código completo com comentários explicativos:

```cpp
//+------------------------------------------------------------------+
//|                                                       MyRobot.mq5 |
//|                        Copyright 2023, MetaQuotes Software Corp. |
//|                                             https://www.metaquotes.net/ |
//+------------------------------------------------------------------+
#include <Trade/Trade.mqh>
input double lotSize = 0.1; // Lote padrão

CTrade trade; // Cria um objeto para operações de trading

//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit()
  {
   return(INIT_SUCCEEDED);
  }
//+------------------------------------------------------------------+
//| Expert deinitialization function                                 |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
  {
   //---
  }

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
  {
   // --- Dados de entrada ---
   double closePrice = iClose(NULL, 0, 0);
   double sma20 = iMA(NULL, 0, 20, 0, MODE_SMA, PRICE_CLOSE);
   double sma200 = iMA(NULL, 0, 200, 0, MODE_SMA, PRICE_CLOSE);

   // --- Determinar tendência ---
   bool bullish = (closePrice > sma20 && sma200 < closePrice); // Preço acima das SMAs → alta
   bool bearish = (closePrice < sma20 && sma200 > closePrice); // Preço abaixo das SMAs → baixa

   bool positionExists = false;
   ulong positionTicket = 0;
   ENUM_POSITION_TYPE currentPositionType = POSITION_TYPE_BUY;

   // --- Verificar se já temos posições ---
   if (PositionsTotal() > 0)
     {
      positionTicket = PositionGetTicket(0); // Ticket da primeira posição encontrada
      if (PositionSelectByTicket(positionTicket))
        {
         currentPositionType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);
         positionExists = true;
        }
     }

   // --- Tratamento de tendência de alta ---
   if (bullish)
     {
      // Se existir uma posição de venda (oposta), feche-a primeiro
      if (positionExists && currentPositionType == POSITION_TYPE_SELL)
        {
         if (trade.PositionClose(positionTicket))
           {
            Print("Fechou posição de venda com sucesso: ", positionTicket);
            positionExists = false;
           }
         else
           {
            Print("Erro ao fechar posição de venda (ticket ", positionTicket, ") - Erro: ", _LastError);
           }
        }

      // Agora abre uma posição comprada se não houver nenhuma posição
      if (!positionExists)
        {
         if (trade.Buy(lotSize, NULL, closePrice, 0, 0, "Comprado por cruzar SMA20"))
           {
            Print("Aberta compra por cruzar SMA20 - Lot: ", lotSize, "Preço: ", closePrice);
           }
         else
           {
            Print("Erro ao abrir compra - Erro: ", _LastError);
           }
        }
     }
   // --- Tratamento de tendência de baixa ---
   else if (bearish)
     {
      // Se existir uma posição de compra (oposta), feche-a primeiro
      if (positionExists && currentPositionType == POSITION_TYPE_BUY)
        {
         if (trade.PositionClose(positionTicket))
           {
            Print("Fechou compra com sucesso: ", positionTicket);
            positionExists = false;
           }
         else
           {
            Print("Erro ao fechar compra (ticket ", positionTicket, ") - Erro: ", _LastError);
           }
        }

      // Abre uma posição vendida se não houver nenhuma posição
      if (!positionExists)
        {
         if (trade.Sell(lotSize, NULL, closePrice, 0, 0, "Vendido por cruzar SMA20"))
           {
            Print("Aberta venda por cruzar SMA20 - Lot: ", lotSize, "Preço: ", closePrice);
           }
         else
           {
            Print("Erro ao abrir venda - Erro: ", _LastError);
           }
        }
     }
  }
//+------------------------------------------------------------------+
```

### Principais Melhorias

| Problema | Como foi resolvido |
|----------|---------------------|
| **Fechamento não ocorre** | Adicionamos verificações detalhadas de sucesso/erro (`_LastError`) e garantimos que `positionExists` seja atualizado imediatamente após o fechamento. |
| **Posição oposta não é fechada antes de abrir nova** | Antes de abrir uma nova posição, primeiro tentamos fechar qualquer posição de tipo oposto (`POSITION_TYPE_SELL` quando queremos comprar, e vice-versa). |
| **Lógica confusa com `else if`** | Utilizamos variáveis booleanas `bullish` e `bearish` para separar claramente as duas tendências, facilitando a leitura e a execução. |
| **Possível fechamento de posição errado** | O código tenta fechar a posição identificada pelo ticket obtido (`PositionGetTicket(0)`). Se houver múltiplas posições, você pode precisar ajustar para selecionar a correta, mas para uso simples com uma única posição funciona bem. |
| **Logs claros** | Imprimimos mensagens de confirmação e erros para facilitar o diagnóstico no Diário do MetaTrader. |

### Passos para Diagnosticar Problemas Futuros

1. **Verifique o Diário (`Journal`)**  
   - Procure por erros (`_LastError`). Isso pode indicar problemas de conexão, parâmetros inválidos ou falta de permissão de trading.

2. **Confira se as condições de crossover estão sendo atendidas**  
   - Em alguns mercados, o cruzamento pode ocorrer em diferentes ticks. Você pode adicionar um pequeno *delay* entre a leitura dos indicadores e a decisão, ou usar `iMA(NULL, 0, 20, 0, MODE_SMA, PRICE_CLOSE, APPEARING)` para incluir sinais futuros.

3. **Teste com um único par**  
   - Execute o robô em um par simples (ex.: EURUSD) e observe se ele abre e fecha a posição conforme esperado. Se ainda não funcionar, verifique se o broker permite trading automático sem autorização adicional.

4. **Atualize a versão do plugin**  
   - Certifique-se de que a versão do `Trade.mqh` e do `CTrade` estão compatíveis com sua plataforma (MetaTrader 5).

---

Com este código revisado, o robô deve **fechar a posição existente antes de abrir uma nova** sempre que houver mudança de tendência, garantindo que não permaneça com a ordem antiga aberta. Se após testar ainda houver dificuldades, compartilhe o conteúdo do **Diário** (ou os últimos erros) para que possamos refinar ainda mais.

