        {
         if (trade.PositionClose(positionTicket))
           {
            Print("Fechou compra com sucesso: ", positionTicket);
            positionExists = false;
           }
         else
           {
            Print("Erro ao fechar compra (ticket ", positionTicket, ") - Erro: ", _LastError);
           }
        }

